<template><div class="page"><div class="section-title"><div><h2>知识库</h2><span class="muted">Markdown 文档上传与索引管理</span></div><n-upload :show-file-list="false" accept=".md,.markdown" :custom-request="upload"><n-button type="primary" :loading="uploading">上传 Markdown</n-button></n-upload></div><div class="metric-grid" style="grid-template-columns:repeat(3,1fr)"><div class="metric"><div><div class="metric-value">{{docs.length}}</div><div class="metric-label">文档总数</div></div></div><div class="metric"><div><div class="metric-value">{{formatSize(totalSize)}}</div><div class="metric-label">索引内容大小</div></div></div><div class="metric"><div><div class="metric-value">{{lastUpdated}}</div><div class="metric-label">最近更新</div></div></div></div><div class="panel"><n-data-table :columns="columns" :data="docs" :loading="loading"/></div></div></template>
<script setup>import {h,ref,computed,onMounted} from 'vue';import {knowledgeApi} from '@/api';const docs=ref([]),loading=ref(false),uploading=ref(false),totalSize=computed(()=>docs.value.reduce((n,d)=>n+d.size,0)),lastUpdated=computed(()=>docs.value.length?new Date(Math.max(...docs.value.map(d=>new Date(d.modified_at)))).toLocaleDateString():'暂无');const columns=[{title:'文件名',key:'name'},{title:'大小',key:'size',render:r=>formatSize(r.size)},{title:'修改时间',key:'modified_at',render:r=>new Date(r.modified_at).toLocaleString()},{title:'状态',key:'indexed',render:r=>r.indexed?'已索引':'待处理'},{title:'操作',key:'action',render:r=>h('button',{class:'link-button',onClick:()=>remove(r.name)},'删除')}];function formatSize(n){if(n<1024)return`${n} B`;if(n<1048576)return`${(n/1024).toFixed(1)} KB`;return`${(n/1048576).toFixed(1)} MB`}async function load(){loading.value=true;try{const r=await knowledgeApi.list();docs.value=r.documents||[]}finally{loading.value=false}}async function upload({file,onFinish,onError}){if(!file.file.name.match(/\.md$/i)){onError();return}uploading.value=true;try{await knowledgeApi.upload(file.file);onFinish();await load()}catch(e){onError(e)}finally{uploading.value=false}}async function remove(name){if(!confirm(`确定删除 ${name}？`))return;await knowledgeApi.remove(name);await load()}onMounted(load)</script>
